"""Apply an orchestrator ``tasks/cancel`` to a Mantle tracker.

The handler locks the tracker, drops every user-facing frame and whatever
sits above the lowest one (a hidden ``call:`` callee, a resume prompt), records
the cancel events for those frames, and publishes ``canceled``. It does not run a
prediction loop: the LLM ``cancel`` tool routes to a follow-up skill after the
drop, and a follow-up here would leave the A2A task open. With no user-facing
skill it only publishes ``canceled``.

Which frames count is decided here. How a dropped frame is recorded is the
executor's rule, shared through :mod:`rasa.mantle.orchestration.cancel_events`.
"""

from __future__ import annotations

from typing import TYPE_CHECKING

import structlog

from rasa.core.a2a_server.engine_adapter import EngineCancelResult
from rasa.dialogue_understanding.stack.dialogue_stack import DialogueStack
from rasa.dialogue_understanding.stack.frames.flow_stack_frame import UserFlowStackFrame
from rasa.dialogue_understanding.stack.frames.mantle_stack_frames import (
    OrderedBlockStackFrame,
    SkillStackFrame,
)
from rasa.mantle.a2a.task_state import user_facing_frames
from rasa.mantle.memory.manager import PENDING_TOOL_CONFIRMATION_ENTRY
from rasa.mantle.orchestration.cancel_events import cancelled_events_for_frames
from rasa.mantle.state.pending_tool_confirmation import PendingToolConfirmation
from rasa.shared.core.events import Event, create_memory_write_event

if TYPE_CHECKING:
    from rasa.core.a2a_server.a2a_output_channel import A2AOutputChannel
    from rasa.core.agent import Agent
    from rasa.mantle.skills.catalog import SkillCatalog
    from rasa.shared.core.trackers import DialogueStateTracker

structlogger = structlog.get_logger()

_PENDING_SLOT = f"system.{PENDING_TOOL_CONFIRMATION_ENTRY}"


class MantleCancelHandler:
    """Dialogue half of ``tasks/cancel`` for a Mantle assistant."""

    @staticmethod
    async def run(
        agent: "Agent",
        sender_id: str,
        output_channel: "A2AOutputChannel",
        *,
        include_default_skills: bool = False,
    ) -> EngineCancelResult:
        """Cancel user-facing skills, then publish the terminal A2A state.

        The skill named in the result is the top user-facing frame before
        the drop. The publisher records that skill; it does not search the
        turn for an earlier ``SkillCancelled``.
        """
        processor = agent.processor
        catalog = _catalog(processor)
        if processor is None or catalog is None:
            result = EngineCancelResult()
            await output_channel.publish_terminal_canceled(result)
            return result

        async with agent.lock_store.lock(sender_id):
            tracker = await processor.get_tracker(sender_id)
            frames = user_facing_frames(
                tracker, catalog, include_default_skills=include_default_skills
            )
            canceled_skill = frames[-1].skill_id if frames else None
            if frames:
                _apply_cancel(
                    tracker,
                    catalog,
                    include_default_skills=include_default_skills,
                )
                await processor.save_tracker(tracker)
            else:
                structlogger.debug(
                    "a2a_server.mantle_cancel.no_user_facing_skill",
                    sender_id=sender_id,
                )
            output_channel.attach_tracker_state(tracker)

        result = EngineCancelResult(canceled_skill=canceled_skill)
        await output_channel.publish_terminal_canceled(result)
        return result


def _catalog(processor: object | None) -> "SkillCatalog | None":
    static_data = getattr(processor, "mantle_static_data", None)
    if static_data is None:
        return None
    catalog = getattr(static_data, "skill_catalog", None)
    return catalog


def _apply_cancel(
    tracker: "DialogueStateTracker",
    catalog: "SkillCatalog",
    *,
    include_default_skills: bool = False,
) -> None:
    """Drop the user-facing frames and record the cancel events for them.

    Anything above the lowest user-facing frame goes too. A hidden callee or a
    resume prompt left on top would otherwise keep running against a skill that
    no longer exists. Frames below that point stay.

    Follows the executor's cancel order: clear a pending tool confirmation the
    dropped frames own, write ``OrderedBlockCancelled`` / ``SkillCancelled``,
    then update the stack. Events are written from the top of the stack down.
    """
    dropped = _frames_to_drop(
        tracker, catalog, include_default_skills=include_default_skills
    )
    dropped_ids = {frame.frame_id for frame in dropped}
    remaining = DialogueStack(
        frames=[
            frame for frame in tracker.stack.frames if frame.frame_id not in dropped_ids
        ]
    )
    recorded = [
        frame
        for frame in dropped
        if isinstance(
            frame, (UserFlowStackFrame, SkillStackFrame, OrderedBlockStackFrame)
        )
    ]

    events: list[Event] = _pending_confirmation_clear_events(tracker, recorded)
    events.extend(cancelled_events_for_frames(catalog, list(reversed(recorded))))
    events.extend(tracker.create_stack_updated_events(remaining))
    tracker.update_with_events(events)


def _frames_to_drop(
    tracker: "DialogueStateTracker",
    catalog: "SkillCatalog",
    *,
    include_default_skills: bool = False,
) -> list:
    """User-facing frames plus every frame stacked above the lowest of them."""
    stack = list(tracker.stack.frames)
    user_facing_ids = {
        frame.frame_id
        for frame in user_facing_frames(
            tracker, catalog, include_default_skills=include_default_skills
        )
    }
    if not user_facing_ids:
        return []
    lowest = min(
        index for index, frame in enumerate(stack) if frame.frame_id in user_facing_ids
    )
    return stack[lowest:]


def _pending_confirmation_clear_events(
    tracker: "DialogueStateTracker",
    frames: "list[UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame]",
) -> list[Event]:
    """Clear the pending tool confirmation when a dropped frame owns it.

    Ownership follows :meth:`PendingToolConfirmation.is_owned_by`: the skill,
    narrowed to the frame when the pause recorded one. A payload that does not
    parse is left alone, as the executor does.
    """
    value = tracker.get_slot(_PENDING_SLOT)
    if not isinstance(value, dict):
        return []
    try:
        pending = PendingToolConfirmation.model_validate(value)
    except ValueError:
        structlogger.warning(
            "a2a_server.mantle_cancel.pending_tool_confirmation.invalid"
        )
        return []
    for frame in frames:
        if pending.is_owned_by(frame_id=frame.frame_id, skill_id=frame.skill_id):
            return [create_memory_write_event(_PENDING_SLOT, None)]
    return []
